{"command":"cat > "$PWD/build/chacha.c" << 'EOF'
/* AVX2 ChaCha20-Poly1305 (RFC 8439), 4 blocks in parallel.
 * encrypt(key32, nonce12, aad, aad_len, pt, pt_len, ct_out, tag_out16)
 */
#include <stdint.h>
#include <string.h>
#include <immintrin.h>

static inline uint32_t load32(const uint8_t *p) {
    uint32_t v;
    memcpy(&v, p, 4);
    return v;
}
static inline void store32(uint8_t *p, uint32_t v) { memcpy(p, &v, 4); }

static inline __m256i rotl_epi32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

/* Quarter round on 4 parallel states.
 * Columns are lanes. We keep state as 16 vectors of 4 lanes.
 */
#define QR(a, b, c, d)                    \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = rotl_epi32(d, 16); \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = rotl_epi32(b, 12); \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = rotl_epi32(d, 8);  \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = rotl_epi32(b, 7);

static void chacha20_xor4(const uint32_t key[8], const uint32_t nonce[3],
                          uint32_t counter, const uint8_t *in, uint8_t *out, int blocks) {
    /* blocks is 1..4. Process `blocks` blocks starting at counter. */
    __m256i s0 = _mm256_set1_epi32(0x61707865);
    __m256i s1 = _mm256_set1_epi32(0x3320646e);
    __m256i s2 = _mm256_set1_epi32(0x79622d32);
    __m256i s3 = _mm256_set1_epi32(0x6b206574);
    __m256i s4 = _mm256_set1_epi32(key[0]);
    __m256i s5 = _mm256_set1_epi32(key[1]);
    __m256i s6 = _mm256_set1_epi32(key[2]);
    __m256i s7 = _mm256_set1_epi32(key[3]);
    __m256i s8 = _mm256_set1_epi32(key[4]);
    __m256i s9 = _mm256_set1_epi32(key[5]);
    __m256i s10 = _mm256_set1_epi32(key[6]);
    __m256i s11 = _mm256_set1_epi32(key[7]);
    __m256i s12 = _mm256_set_epi32(counter + 3, counter + 2, counter + 1, counter);
    __m256i s13 = _mm256_set1_epi32(nonce[0]);
    __m256i s14 = _mm256_set1_epi32(nonce[1]);
    __m256i s15 = _mm256_set1_epi32(nonce[2]);

    __m256i x0=s0,x1=s1,x2=s2,x3=s3,x4=s4,x5=s5,x6=s6,x7=s7;
    __m256i x8=s8,x9=s9,x10=s10,x11=s11,x12=s12,x13=s13,x14=s14,x15=s15;

    for (int i = 0; i < 10; i++) {
        /* column rounds */
        QR(x0, x4, x8, x12);
        QR(x1, x5, x9, x13);
        QR(x2, x6, x10, x14);
        QR(x3, x7, x11, x15);
        /* diagonal rounds */
        QR(x0, x5, x10, x15);
        QR(x1, x6, x11, x12);
        QR(x2, x7, x8, x13);
        QR(x3, x4, x9, x14);
    }
    x0 = _mm256_add_epi32(x0, s0);
    x1 = _mm256_add_epi32(x1, s1);
    x2 = _mm256_add_epi32(x2, s2);
    x3 = _mm256_add_epi32(x3, s3);
    x4 = _mm256_add_epi32(x4, s4);
    x5 = _mm256_add_epi32(x5, s5);
    x6 = _mm256_add_epi32(x6, s6);
    x7 = _mm256_add_epi32(x7, s7);
    x8 = _mm256_add_epi32(x8, s8);
    x9 = _mm256_add_epi32(x9, s9);
    x10 = _mm256_add_epi32(x10, s10);
    x11 = _mm256_add_epi32(x11, s11);
    x12 = _mm256_add_epi32(x12, s12);
    x13 = _mm256_add_epi32(x13, s13);
    x14 = _mm256_add_epi32(x14, s14);
    x15 = _mm256_add_epi32(x15, s15);

    /* Transpose lanes into per-block keystream and xor.
     * Lane i of each word is block i. We extract lane by lane. */
    uint32_t lane[4][16];
    __m256i words[16] = {x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15};
    for (int w = 0; w < 16; w++) {
        uint32_t tmp[8];
        _mm256_storeu_si256((__m256i *)tmp, words[w]);
        /* set_epi32(c3,c2,c1,c0) stores c0 at lowest address */
        lane[0][w] = tmp[0];
        lane[1][w] = tmp[1];
        lane[2][w] = tmp[2];
        lane[3][w] = tmp[3];
    }
    for (int b = 0; b < blocks; b++) {
        const uint8_t *src = in ? in + b * 64 : NULL;
        uint8_t *dst = out + b * 64;
        uint8_t ks[64];
        for (int w = 0; w < 16; w++) store32(ks + 4 * w, lane[b][w]);
        if (src) {
            for (int i = 0; i < 64; i++) dst[i] = src[i] ^ ks[i];
        } else {
            memcpy(dst, ks, 64);
        }
    }
}

/* ---- Poly1305 (RFC 8439) ---- */
typedef struct {
    uint32_t r[5];
    uint32_t h[5];
    uint32_t pad[4];
    uint8_t buf[16];
    size_t buf_used;
} poly1305_ctx;

static void poly1305_init(poly1305_ctx *st, const uint8_t key[32]) {
    memset(st, 0, sizeof(*st));
    /* r clamped */
    uint32_t t0 = load32(key);
    uint32_t t1 = load32(key + 4);
    uint32_t t2 = load32(key + 8);
    uint32_t t3 = load32(key + 12);
    st->r[0] = t0 & 0x3ffffff;
    st->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    st->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    st->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    st->r[4] = (t3 >> 8) & 0x00fffff;
    st->pad[0] = load32(key + 16);
    st->pad[1] = load32(key + 20);
    st->pad[2] = load32(key + 24);
    st->pad[3] = load32(key + 28);
}

static void poly1305_blocks(poly1305_ctx *st, const uint8_t *m, size_t bytes, uint32_t hibit) {
    const uint32_t r0 = st->r[0], r1 = st->r[1], r2 = st->r[2], r3 = st->r[3], r4 = st->r[4];
    const uint32_t s1 = r1 * 5, s2 = r2 * 5, s3 = r3 * 5, s4 = r4 * 5;
    uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];

    while (bytes >= 16) {
        uint32_t t0 = load32(m);
        uint32_t t1 = load32(m + 4);
        uint32_t t2 = load32(m + 8);
        uint32_t t3 = load32(m + 12);

        h0 += t0 & 0x3ffffff;
        h1 += ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
        h2 += ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
        h3 += ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
        h4 += (t3 >> 8) | hibit;

        uint64_t d0 = (uint64_t)h0 * r0 + (uint64_t)h1 * s4 + (uint64_t)h2 * s3 + (uint64_t)h3 * s2 + (uint64_t)h4 * s1;
        uint64_t d1 = (uint64_t)h0 * r1 + (uint64_t)h1 * r0 + (uint64_t)h2 * s4 + (uint64_t)h3 * s3 + (uint64_t)h4 * s2;
        uint64_t d2 = (uint64_t)h0 * r2 + (uint64_t)h1 * r1 + (uint64_t)h2 * r0 + (uint64_t)h3 * s4 + (uint64_t)h4 * s3;
        uint64_t d3 = (uint64_t)h0 * r3 + (uint64_t)h1 * r2 + (uint64_t)h2 * r1 + (uint64_t)h3 * r0 + (uint64_t)h4 * s4;
        uint64_t d4 = (uint64_t)h0 * r4 + (uint64_t)h1 * r3 + (uint64_t)h2 * r2 + (uint64_t)h3 * r1 + (uint64_t)h4 * r0;

        uint64_t c;
        c = d0 >> 26; h0 = (uint32_t)d0 & 0x3ffffff; d1 += c;
        c = d1 >> 26; h1 = (uint32_t)d1 & 0x3ffffff; d2 += c;
        c = d2 >> 26; h2 = (uint32_t)d2 & 0x3ffffff; d3 += c;
        c = d3 >> 26; h3 = (uint32_t)d3 & 0x3ffffff; d4 += c;
        c = d4 >> 26; h4 = (uint32_t)d4 & 0x3ffffff; h0 += (uint32_t)c * 5;
        c = h0 >> 26; h0 &= 0x3ffffff; h1 += (uint32_t)c;

        m += 16;
        bytes -= 16;
    }
    st->h[0] = h0; st->h[1] = h1; st->h[2] = h2; st->h[3] = h3; st->h[4] = h4;
}

static void poly1305_update(poly1305_ctx *st, const uint8_t *m, size_t bytes) {
    if (st->buf_used) {
        size_t want = 16 - st->buf_used;
        if (want > bytes) want = bytes;
        memcpy(st->buf + st->buf_used, m, want);
        st->buf_used += want;
        m += want;
        bytes -= want;
        if (st->buf_used == 16) {
            poly1305_blocks(st, st->buf, 16, 1u << 24);
            st->buf_used = 0;
        }
    }
    if (bytes >= 16) {
        size_t n = bytes & ~(size_t)15;
        poly1305_blocks(st, m, n, 1u << 24);
        m += n;
        bytes -= n;
    }
    if (bytes) {
        memcpy(st->buf + st->buf_used, m, bytes);
        st->buf_used += bytes;
    }
}

static void poly1305_finish(poly1305_ctx *st, uint8_t mac[16]) {
    if (st->buf_used) {
        st->buf[st->buf_used] = 1;
        for (size_t i = st->buf_used + 1; i < 16; i++) st->buf[i] = 0;
        poly1305_blocks(st, st->buf, 16, 0);
    }
    uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];
    uint32_t c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    /* compute h + -p */
    uint32_t g0 = h0 + 5;
    c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);

    uint32_t mask = (g4 >> 31) - 1u; /* all 1s if g4 didn't underflow */
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t f0 = ((h0) | ((uint64_t)h1 << 26)) + st->pad[0];
    uint64_t f1 = ((h1 >> 6) | ((uint64_t)h2 << 20)) + st->pad[1];
    uint64_t f2 = ((h2 >> 12) | ((uint64_t)h3 << 14)) + st->pad[2];
    uint64_t f3 = ((h3 >> 18) | ((uint64_t)h4 << 8)) + st->pad[3];
    f1 += f0 >> 32; f2 += f1 >> 32; f3 += f2 >> 32;
    store32(mac + 0, (uint32_t)f0);
    store32(mac + 4, (uint32_t)f1);
    store32(mac + 8, (uint32_t)f2);
    store32(mac + 12, (uint32_t)f3);
}

static void write_le64(uint8_t *p, uint64_t v) {
    for (int i = 0; i < 8; i++) p[i] = (uint8_t)(v >> (8 * i));
}

/* AEAD encrypt. ct must have pt_len bytes. */
void chacha20_poly1305_encrypt(
    const uint8_t key[32],
    const uint8_t nonce[12],
    const uint8_t *aad, size_t aad_len,
    const uint8_t *pt, size_t pt_len,
    uint8_t *ct,
    uint8_t tag[16]
) {
    uint32_t k[8], n[3];
    for (int i = 0; i < 8; i++) k[i] = load32(key + 4 * i);
    for (int i = 0; i < 3; i++) n[i] = load32(nonce + 4 * i);

    /* Poly1305 key = ChaCha20(key, nonce, counter=0) first 32 bytes */
    uint8_t block0[64];
    chacha20_xor4(k, n, 0, NULL, block0, 1);

    poly1305_ctx poly;
    poly1305_init(&poly, block0);

    poly1305_update(&poly, aad, aad_len);
    if (aad_len % 16) {
        uint8_t zeros[16] = {0};
        poly1305_update(&poly, zeros, 16 - (aad_len % 16));
    }

    /* encrypt plaintext, counter starts at 1, 4 blocks at a time */
    size_t off = 0;
    uint32_t counter = 1;
    while (off + 256 <= pt_len) {
        chacha20_xor4(k, n, counter, pt + off, ct + off, 4);
        off += 256;
        counter += 4;
    }
    size_t rem_blocks_bytes = pt_len - off;
    if (rem_blocks_bytes) {
        int full = (int)(rem_blocks_bytes / 64);
        size_t tail = rem_blocks_bytes % 64;
        uint8_t tmp_in[256];
        uint8_t tmp_out[256];
        memset(tmp_in, 0, sizeof(tmp_in));
        if (full) memcpy(tmp_in, pt + off, full * 64);
        if (tail) memcpy(tmp_in + full * 64, pt + off + full * 64, tail);
        int blocks = full + (tail ? 1 : 0);
        if (blocks == 0) blocks = 1;
        chacha20_xor4(k, n, counter, tmp_in, tmp_out, blocks);
        memcpy(ct + off, tmp_out, rem_blocks_bytes);
    }

    poly1305_update(&poly, ct, pt_len);
    if (pt_len % 16) {
        uint8_t zeros[16] = {0};
        poly1305_update(&poly, zeros, 16 - (pt_len % 16));
    }
    uint8_t lens[16];
    write_le64(lens, aad_len);
    write_le64(lens + 8, pt_len);
    poly1305_update(&poly, lens, 16);
    poly1305_finish(&poly, tag);

    /* wipe */
    memset(block0, 0, sizeof(block0));
}
