#include <nettle/chacha-poly1305.h>
#include <nettle/chacha.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40000u * 1024u;
    uint8_t key[32], nonce[12];
    memset(key, 1, 32);
    memset(nonce, 2, 12);
    uint8_t *pt = malloc(n);
    uint8_t *ct = malloc(n);
    uint8_t tag[16];
    uint8_t aad[32];
    memset(pt, 3, n);
    memset(aad, 4, 32);

    struct chacha_poly1305_ctx ctx;
    /* warmup */
    chacha_poly1305_set_key(&ctx, key);
    chacha_poly1305_set_nonce(&ctx, nonce);
    chacha_poly1305_update(&ctx, 32, aad);
    chacha_poly1305_encrypt(&ctx, 1024, ct, pt);
    chacha_poly1305_digest(&ctx, 16, tag);

    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        chacha_poly1305_set_key(&ctx, key);
        chacha_poly1305_set_nonce(&ctx, nonce);
        chacha_poly1305_update(&ctx, 32, aad);
        chacha_poly1305_encrypt(&ctx, n, ct, pt);
        chacha_poly1305_digest(&ctx, 16, tag);
    }
    double t1 = now();
    printf("nettle %.4f s/op  tag %02x%02x\n", (t1-t0)/reps, tag[0], tag[1]);

    /* also raw chacha */
    struct chacha_ctx cctx;
    chacha_set_key(&cctx, key);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        chacha_set_nonce(&cctx, nonce); /* might be 8-byte? check */
    }
    printf("note nonce fn exists\n");
    return 0;
}
