static void poly1305_finish(poly1305_ctx *st, uint8_t mac[16]) {
    if (st->buf_used) {
        st->buf[st->buf_used] = 1;
        for (size_t i = st->buf_used + 1; i < 16; i++) st->buf[i] = 0;
        poly1305_blocks(st, st->buf, 16, 0);
    }
    uint32_t h0 = st->h[0], h1 = st->h[1], h2 = st->h[2], h3 = st->h[3], h4 = st->h[4];
    uint32_t c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;

    /* compute h + -p */
    uint32_t g0 = h0 + 5;
    c = g0 >> 26; g0 &= 0x3ffffff;
    uint32_t g1 = h1 + c; c = g1 >> 26; g1 &= 0x3ffffff;
    uint32_t g2 = h2 + c; c = g2 >> 26; g2 &= 0x3ffffff;
    uint32_t g3 = h3 + c; c = g3 >> 26; g3 &= 0x3ffffff;
    uint32_t g4 = h4 + c - (1u << 26);

    uint32_t mask = (g4 >> 31) - 1u; /* all 1s if g4 didn't underflow */
    g0 &= mask; g1 &= mask; g2 &= mask; g3 &= mask; g4 &= mask;
    mask = ~mask;
    h0 = (h0 & mask) | g0;
    h1 = (h1 & mask) | g1;
    h2 = (h2 & mask) | g2;
    h3 = (h3 & mask) | g3;
    h4 = (h4 & mask) | g4;

    uint64_t f0 = ((uint64_t)h0 | ((uint64_t)h1 << 26)) + st->pad[0];
    uint64_t f1 = ((h1 >> 6) | ((uint64_t)h2 << 20)) + st->pad[1];
    uint64_t f2 = ((h2 >> 12) | ((uint64_t)h3 << 14)) + st->pad[2];
    uint64_t f3 = ((h3 >> 18) | ((uint64_t)h4 << 8)) + st->pad[3];
    f1 += f0 >> 32; f2 += f1 >> 32; f3 += f2 >> 32;
    store32(mac + 0, (uint32_t)f0);
    store32(mac + 4, (uint32_t)f1);
    store32(mac + 8, (uint32_t)f2);
    store32(mac + 12, (uint32_t)f3);
}

