#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static int evp_encrypt(const uint8_t *key, const uint8_t *nonce,
                       const uint8_t *aad, size_t aad_len,
                       const uint8_t *pt, uint8_t *ct, size_t n, uint8_t tag[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl = 0, tot = 0;
    if (!EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL)) return 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL)) return 0;
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce)) return 0;
    if (aad_len && !EVP_EncryptUpdate(ctx, NULL, &outl, aad, (int)aad_len)) return 0;
    /* chunk to avoid int overflow, though n fits */
    size_t off = 0;
    while (off < n) {
        int chunk = (n - off) > 1<<20 ? 1<<20 : (int)(n - off);
        if (!EVP_EncryptUpdate(ctx, ct + off, &outl, pt + off, chunk)) return 0;
        off += outl;
    }
    if (!EVP_EncryptFinal_ex(ctx, ct + off, &outl)) return 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag)) return 0;
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

/* raw chacha via EVP? use EVP_chacha20 */
static int chacha_crypt(const uint8_t *key, const uint8_t *nonce12, uint32_t counter,
                        const uint8_t *pt, uint8_t *ct, size_t n) {
    /* OpenSSL ChaCha20 EVP uses 16-byte IV: counter(4 LE) || nonce(12) */
    uint8_t iv[16];
    memcpy(iv, &counter, 4);
    memcpy(iv+4, nonce12, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl=0;
    if (!EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv)) return 0;
    size_t off=0;
    while (off < n) {
        int chunk = (n-off) > 1<<20 ? 1<<20 : (int)(n-off);
        if (!EVP_EncryptUpdate(ctx, ct+off, &outl, pt+off, chunk)) return 0;
        off += outl;
    }
    EVP_EncryptFinal_ex(ctx, ct+off, &outl);
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

typedef struct {
    const uint8_t *key, *nonce, *pt;
    uint8_t *ct;
    size_t n;
    uint32_t counter;
} job;

static void *worker(void *arg) {
    job *j = arg;
    chacha_crypt(j->key, j->nonce, j->counter, j->pt, j->ct, j->n);
    return NULL;
}

int main() {
    size_t n = 40000u * 1024u;
    uint8_t *pt = malloc(n);
    uint8_t *ct = malloc(n);
    memset(pt, 3, n);
    uint8_t key[32], nonce[12], tag[16], aad[32];
    memset(key, 1, 32); memset(nonce, 2, 12); memset(aad, 4, 32);

    double t0 = now();
    evp_encrypt(key, nonce, aad, 32, pt, ct, n, tag);
    double t1 = now();
    printf("single aead %.4f\n", t1-t0);

    t0 = now();
    chacha_crypt(key, nonce, 1, pt, ct, n);
    t1 = now();
    printf("single chacha %.4f\n", t1-t0);

    for (int threads = 1; threads <= 6; threads++) {
        pthread_t th[16];
        job jobs[16];
        size_t chunk = (n / threads) & ~63u;
        t0 = now();
        for (int i = 0; i < threads; i++) {
            size_t off = i * chunk;
            size_t len = (i == threads-1) ? n - off : chunk;
            jobs[i].key = key; jobs[i].nonce = nonce;
            jobs[i].pt = pt + off; jobs[i].ct = ct + off; jobs[i].n = len;
            jobs[i].counter = 1 + (uint32_t)(off / 64);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
        t1 = now();
        printf("chacha threads %d  %.4f\n", threads, t1-t0);
    }

    /* memcpy bandwidth */
    t0 = now();
    for (int i = 0; i < 5; i++) memcpy(ct, pt, n);
    t1 = now();
    printf("memcpy %.4f  (%.1f GB/s)\n", (t1-t0)/5, (n/1e9)/((t1-t0)/5));
    return 0;
}
EOF
