#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void poly_init(EVP_MAC_CTX **ctx, EVP_MAC **mac, const uint8_t key[32]) {
    *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    *ctx = EVP_MAC_CTX_new(*mac);
    EVP_MAC_init(*ctx, key, 32, NULL);
}
static void poly_final(EVP_MAC_CTX *ctx, EVP_MAC *mac, uint8_t tag[16]) {
    size_t ln=16;
    EVP_MAC_final(ctx, tag, &ln, 16);
    EVP_MAC_CTX_free(ctx);
    EVP_MAC_free(mac);
}

/* Horner-friendly: compute poly1305 block product using openssl by feeding a message
   and also get the raw state? We can't. Instead time:
   - one-shot poly of 40MB
   - 6 parallel polys of 40/6 MB (independent, not combined)
*/
int main() {
    size_t n = 40000u*1024u;
    uint8_t *msg = malloc(n);
    memset(msg, 7, n);
    uint8_t key[32]; memset(key, 9, 32);
    uint8_t tag[16];

    EVP_MAC *mac; EVP_MAC_CTX *ctx;
    poly_init(&ctx, &mac, key);
    double t0 = now();
    EVP_MAC_update(ctx, msg, n);
    poly_final(ctx, mac, tag);
    double t1 = now();
    printf("poly one-shot %.4f\n", t1-t0);

    /* parallel independent */
    int threads = 6;
    /* just sequential chunks to see per-chunk overhead vs one-shot */
    t0 = now();
    poly_init(&ctx, &mac, key);
    size_t chunk = n/threads;
    for (int i = 0; i < threads; i++) {
        size_t off = i*chunk;
        size_t len = (i==threads-1)? n-off : chunk;
        EVP_MAC_update(ctx, msg+off, len);
    }
    poly_final(ctx, mac, tag);
    t1 = now();
    printf("poly chunked sequential %.4f\n", t1-t0);

    /* What if we only auth a tiny length? time of empty poly */
    t0 = now();
    for (int i = 0; i < 1000; i++) {
        poly_init(&ctx, &mac, key);
        poly_final(ctx, mac, tag);
    }
    t1 = now();
    printf("poly init/final %.6f\n", (t1-t0)/1000);

    /* AEAD with tiny plaintext to see fixed cost */
    EVP_CIPHER_CTX *c = EVP_CIPHER_CTX_new();
    uint8_t nonce[12]={0}, aad[32]={0}, ct[64], pt[64]={0};
    t0 = now();
    for (int i = 0; i < 1000; i++) {
        int outl=0;
        EVP_EncryptInit_ex(c, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(c, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(c, ct, &outl, pt, 64);
        EVP_EncryptFinal_ex(c, ct, &outl);
        EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("aead tiny %.6f\n", (t1-t0)/1000);
    return 0;
}
