#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void chacha_crypt(const uint8_t *key, const uint8_t *nonce12, uint32_t counter,
                        const uint8_t *pt, uint8_t *ct, size_t n) {
    uint8_t iv[16];
    memcpy(iv, &counter, 4);
    memcpy(iv+4, nonce12, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv);
    size_t off=0;
    while (off < n) {
        size_t left = n-off;
        int chunk = left > 0x40000000u ? 0x40000000 : (int)left;
        EVP_EncryptUpdate(ctx, ct+off, &outl, pt+off, chunk);
        off += (size_t)outl;
    }
    EVP_EncryptFinal_ex(ctx, ct+off, &outl);
    EVP_CIPHER_CTX_free(ctx);
}

typedef struct {
    const uint8_t *key, *nonce, *pt;
    uint8_t *ct;
    size_t n;
    uint32_t counter;
} job;

static void *worker(void *arg) {
    job *j = arg;
    chacha_crypt(j->key, j->nonce, j->counter, j->pt, j->ct, j->n);
    return NULL;
}

static void poly_mac(const uint8_t key[32], const uint8_t *m, size_t n, uint8_t tag[16]) {
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    EVP_MAC_CTX *ctx = EVP_MAC_CTX_new(mac);
    EVP_MAC_init(ctx, key, 32, NULL);
    size_t off=0;
    while (off < n) {
        size_t left = n-off;
        size_t chunk = left > 0x40000000u ? 0x40000000u : left;
        EVP_MAC_update(ctx, m+off, chunk);
        off += chunk;
    }
    size_t ln=16;
    EVP_MAC_final(ctx, tag, &ln, 16);
    EVP_MAC_CTX_free(ctx);
    EVP_MAC_free(mac);
}

int main() {
    size_t n = 40000ull*1024ull;
    uint8_t *pt = malloc(n), *ct = malloc(n);
    memset(pt, 3, n);
    uint8_t key[32], nonce[12], tag[16], otk[64];
    memset(key, 1, 32); memset(nonce, 2, 12);

    /* poly key */
    chacha_crypt(key, nonce, 0, NULL, otk, 64); /* NULL src? EVP may not like NULL. use zeros */
    uint8_t zeros[64]={0};
    chacha_crypt(key, nonce, 0, zeros, otk, 64);

    int threads = 4;
    pthread_t th[8];
    job jobs[8];
    size_t chunk = (n / threads) & ~63ull;

    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < threads; i++) {
            size_t off = (size_t)i * chunk;
            size_t len = (i == threads-1) ? n - off : chunk;
            jobs[i] = (job){key, nonce, pt+off, ct+off, len, 1 + (uint32_t)(off/64)};
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
        /* poly over ciphertext + lengths. For timing, just mac ct */
        poly_mac(otk, ct, n, tag);
    }
    double t1 = now();
    printf("parallel chacha + poly %.4f\n", (t1-t0)/reps);

    /* overlap? poly can't start until ct ready. That's the number above. */

    /* threads=6 */
    threads = 6;
    chunk = (n / threads) & ~63ull;
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < threads; i++) {
            size_t off = (size_t)i * chunk;
            size_t len = (i == threads-1) ? n - off : chunk;
            jobs[i] = (job){key, nonce, pt+off, ct+off, len, 1 + (uint32_t)(off/64)};
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
        poly_mac(otk, ct, n, tag);
    }
    t1 = now();
    printf("6 thr + poly %.4f\n", (t1-t0)/reps);
    return 0;
}
